-- Migration 0007: Auto-seed 38 Provinces, 514 Regencies/Cities, National Emergency Contacts, and Initial Verified Places

-- 1. Provinces (38)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug;

-- 2. Regencies & Cities (514)
ON CONFLICT (id) DO UPDATE SET
  province_id = EXCLUDED.province_id,
  name = EXCLUDED.name,
  short_name = EXCLUDED.short_name,
  slug = EXCLUDED.slug,
  latitude = EXCLUDED.latitude,
  longitude = EXCLUDED.longitude,
  tier = EXCLUDED.tier,
  timezone = EXCLUDED.timezone,
  updated_at = now();

-- 3. Verified National Emergency Contacts
    city_id, service_name, category, phone_number,
    is_toll_free, is_24_hours, sort_order, is_active, source_url, verified_at
)
SELECT
    NULL, v.service_name, v.category, v.phone_number,
    v.is_toll_free, true, v.sort_order, true, v.source_url, now()
FROM (
    VALUES
        ('Layanan Darurat Terpadu Nasional (112)', 'umum', '112', true, 1, 'https://layanan112.komdigi.go.id/'),
        ('Ambulans & Gawat Darurat Medis SPGDT (119)', 'medis', '119', true, 2, 'https://kemkes.go.id/'),
        ('Kepolisian Republik Indonesia (110)', 'polisi', '110', true, 3, 'https://polri.go.id/'),
        ('Pemadam Kebakaran & Penyelamatan', 'damkar', '113', false, 4, 'https://kemendagri.go.id/'),
        ('BASARNAS (Pencarian & Pertolongan SAR)', 'sar', '115', true, 5, 'https://basarnas.go.id/'),
        ('Posko Bencana Nasional (BNPB)', 'bencana', '129', false, 6, 'https://bnpb.go.id/')
) AS v(service_name, category, phone_number, is_toll_free, sort_order, source_url)
WHERE NOT EXISTS (
    SELECT 1 FROM emergency_contacts e
    WHERE e.city_id IS NULL AND e.phone_number = v.phone_number
);

